const sigOf = el => {                          // r2 §5: pre-order теги ВЕРХНИМ регистром через '>', глубина ≤3
  const out = [];
  (function walk(n, d) {
    if (!n || n.nodeType !== 1 || d > 3) return;
    out.push(n.tagName.toUpperCase());
    for (let c = n.firstElementChild; c; c = c.nextElementSibling) walk(c, d + 1);
  })(el, 1);
  return out.join('>');
