const subtreeDepth = (el, cap) => {            // фактическая глубина поддерева (cap 6)
  let max = 1;
  (function walk(n, cur) {
    if (cur > cap) return;
    for (let c = n.firstElementChild; c; c = c.nextElementSibling) { max = Math.max(max, cur + 1); walk(c, cur + 1); }
  })(el, 1);
  return max;
