const CLIENT_FILE = PLUGIN_DIR ? path.join(PLUGIN_DIR, 'client.js') : ''
// XJJ_TEMPLATE_FILE 只给测试用：让守卫能自己造「模板比产物新」的场景（否则构建闸门只有单向门齿）
