const hashString = fnv1aHex;                                  /* совместимость */
const sigHashIn = sig => SALT + '>' + String(sig).toUpperCase();   /* вход sigHash  */
const urlHashIn = href => SALT + 'URL>' + String(href || '');      /* вход urlHash  */
