/* zipBuild(files) → Uint8Array. files: [{name, data:Uint8Array|string, store?}]
   КОНТРАКТ: name/data нормализуются к байтам немедленно; размеры ТОЛЬКО в байтах. */
async function zipBuild(files) {
  const norm = [];
