  for (const m of cd.messages) L.push('[' + (m.index + 1) + '] ' + m.role.toUpperCase() + (m.role === 'unknown' ? ' (evidence: ' + m.roleEvidence.method + ')' : ''), m.text || '(пусто)', '');
