    document.documentElement.appendChild(a);
    a.click();
    setTimeout(() => { try { URL.revokeObjectURL(a.href); a.remove(); } catch (e) { journal.debug('export', 'revoke-fail', String(e && e.message || e)); } }, 4000);
    return { kind: 'file', name, mime: blob.type, blob };
