  security: (s, m, d) => jpush('security', s, m, d),
  net: (host, bytes, via) => jpush('net', 'network', host + ' ' + bytes + 'B via ' + via, null),
  dump: n => journalBuf.slice(-(n || JOURNAL_CAP)),
  stats: () => {
    const s = {};
