};

/* --- L0.2 Хэш-канон PML §5: FNV-1a 32, UTF-8 байты, hex8 lowercase --- */
const ENC = new TextEncoder();
const utf8 = s => ENC.encode(String(s == null ? '' : s));
const byteLen = s => utf8(s).length;
