  function askAndSaveKey() {
    const key = window.prompt(
      '请输入微信读书 WeRead API Key（以 wrk- 开头）\n\n官方获取页：https://weread.qq.com/r/weread-skills',
      getKey()
    );

    if (key === null) return false;

    const clean = key.trim();

    if (!clean.startsWith('wrk-')) {
      window.alert('这个 Key 看起来不对：应当以 wrk- 开头。');
      return false;
    }

    GM_setValue(KEY_NAME, clean);
    setStatus('Key 已保存，准备重新读取……', true);
    return true;
  }

  function api(apiName, params = {}) {
    const key = getKey();

    if (!key) {
      return Promise.reject(
        new Error('还没有设置 WeRead API Key')
      );
    }

    return new Promise((resolve, reject) => {
      GM_xmlhttpRequest({
        method: 'POST',
        anonymous: true,
        url: API,

        headers: {
          Authorization: `Bearer ${key}`,
          'Content-Type': 'application/json'
        },

        data: JSON.stringify({
          api_name: apiName,
          ...params,
          skill_version: SKILL_VERSION
        }),

        timeout: 15000,

        onload(res) {
          let data;

          try {
            data = JSON.parse(res.responseText || '{}');
          } catch (_) {
            reject(
              new Error(
                `API 返回内容无法解析（HTTP ${res.status}）`
              )
            );
            return;
          }

          const errcode =
            data.errcode ??
            data.errCode ??
            0;

          if (
            res.status < 200 ||
            res.status >= 300 ||
            Number(errcode) !== 0
          ) {
            reject(
              new Error(
                data.errmsg ||
                data.message ||
                `API 错误：HTTP ${res.status}, errcode ${errcode}`
              )
            );
            return;
          }

          // upgrade_info is advisory; use this response without retrying it.
          if (data.upgrade_info) upgradeAvailable = true;
          resolve(data);
        },

        onerror() {
          reject(
            new Error('连接微信读书 API 失败')
          );
        },

        ontimeout() {
          reject(
            new Error('连接微信读书 API 超时')
          );
        }
      });
    });
  }

