import { execFileSync } from "node:child_process";

const branch = process.env.GITHUB_HEAD_REF || process.env.GITHUB_REF_NAME || "";

if (branch !== "refactor/6.5") {
  console.log("6.5 ancestry check skipped outside refactor/6.5");
